// Ordre d'affichage stable : par famille, puis par numéro de test (A2 avant A10).
testCases.sort((a, b) => a.family.localeCompare(b.family) || parseInt(a.id.slice(1), 10) - parseInt(b.id.slice(1), 10));

/// Échappe le HTML d'un texte (les chevrons de « account-<username> » disparaissaient sinon,
/// interprétés comme une balise).
function escapeHTML(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/// Texte d'un test prêt à insérer en HTML : échappé, avec les `extraits` entre accents graves
/// rendus en police à chasse fixe.
function formatText(s) {
  return escapeHTML(s).replace(/`([^`]+)`/g, '<code>$1</code>');
}
